import random

def build_track(segs):
    # segs sorted by start, non-overlapping; returns P,V arrays as add_loc would
    P=[]; V=[]
    for s,e,v in segs:
        if e<=0: continue
        if s<0: s=0
        if not P:
            if s>0:
                P.append(s); V.append(0.0)
            P.append(e); V.append(v)
        else:
            pre=V[-1]
            if pre==v:
                P[-1]=e
            else:
                P.append(e); V.append(v)
    return P,V

def close_peak(peak_content, out):
    if not peak_content:
        raise IndexError("empty")
    peak_length = peak_content[-1][1]-peak_content[0][0]
    if peak_length >= 0:
        tsummit=[]; summit=0; summit_value=0
        for tstart,tend,tvalue in peak_content:
            if not summit_value or summit_value < tvalue:
                tsummit=[int((tend+tstart)/2)]
                summit_value=tvalue
            elif summit_value==tvalue:
                tsummit.append(int((tend+tstart)/2))
        summit = tsummit[int((len(tsummit)+1)/2)-1]
        out.append((peak_content[0][0], peak_content[-1][1], summit, summit_value))
    return True

def current(segs, cands):
    P,V = build_track(segs)
    out=[]
    for chrom in ['x']:
        ps=list(P); vs=list(V); peaks=sorted(cands, key=lambda c:c[0])
        peak_content=[]
        pre_p=0
        if not ps or not peaks:
            # mirror exceptions? initial reads raise
            if not ps: return out
            if not peaks: return out
        pi=0; vi=0; pki=0
        p=ps[0]; v=vs[0]; peak=peaks[0]
        peak_s=peak[0]; peak_e=peak[1]
        while True:
            if p > peak_s and peak_e > pre_p:
                s,e = sorted([p, peak_s, peak_e, pre_p])[1:3]
                peak_content.append((s,e,v))
                try:
                    pre_p=p
                    pi+=1; p=ps[pi]; v=vs[pi]
                except Exception:
                    break
            elif pre_p >= peak_e:
                # with guard
                if peak_content:
                    close_peak(peak_content,out)
                peak_content=[]
                try:
                    pki+=1; peak=peaks[pki]; peak_s=peak[0]; peak_e=peak[1]
                except Exception:
                    break
            elif peak_s >= p:
                try:
                    pre_p=p
                    pi+=1; p=ps[pi]; v=vs[pi]
                except Exception:
                    break
            else:
                raise Exception("no way")
        if peak_content:
            close_peak(peak_content,out)
    return out

def reference(segs, cands):
    P,V = build_track(segs)
    S=[]
    prev=0
    for i in range(len(P)):
        S.append((prev,P[i],V[i])); prev=P[i]
    out=[]
    cands=sorted(cands,key=lambda c:c[0])
    j=0; n=len(S)
    for (cs,ce) in cands:
        # skip segments ending at/before candidate start
        while j<n and S[j][1] <= cs:
            j+=1
        if j>=n:
            break
        if S[j][0] >= ce:
            # no overlap, keep segment
            continue
        coll=[]
        while j<n:
            s,e,v=S[j]
            if s >= ce or e <= cs:
                break
            coll.append((max(s,cs), min(e,ce), v))
            j+=1
            # note: consumed whole segment even if e > ce
        if coll:
            # close_peak logic
            peak_length = coll[-1][1]-coll[0][0]
            if peak_length >= 0:
                tsummit=[]; summit_value=0
                for tstart,tend,tvalue in coll:
                    if not summit_value or summit_value < tvalue:
                        tsummit=[int((tend+tstart)/2)]; summit_value=tvalue
                    elif summit_value==tvalue:
                        tsummit.append(int((tend+tstart)/2))
                summit=tsummit[int((len(tsummit)+1)/2)-1]
                out.append((coll[0][0], coll[-1][1], summit, summit_value))
    return out

# fuzz
def rand_case(rng):
    # generate contiguous segments covering [0, end)
    n=rng.randint(1,8)
    pts=sorted(set([0]+[rng.randint(1,100) for _ in range(n)]))
    pts=[p for p in pts if p>0]
    if not pts: pts=[100]
    segs=[]
    prev=0
    for p in pts:
        segs.append((prev,p,round(rng.uniform(0,10),1)))
        prev=p
    # candidates valid intervals
    m=rng.randint(1,8)
    cands=[]
    for _ in range(m):
        a=rng.randint(0,130); b=rng.randint(a+1,150)
        cands.append((a,b))
    return segs,cands

