# quick simulation of guarded algorithm for fixture cases
def build_track(segments):
    P=[]; V=[]
    for s,e,v in sorted(segments, key=lambda x:x[0]):
        if e<=0: continue
        if s<0: s=0
        if not P:
            if s>0:
                P.append(s); V.append(0.0)
            P.append(e); V.append(v)
        else:
            if V[-1]==v:
                P[-1]=e
            else:
                P.append(e); V.append(v)
    return P,V

def refine(segments, cands):
    P,V=build_track(segments)
    peaks=sorted(cands,key=lambda c:c[0])
    out=[]; content=[]; pre_p=0
    pi=0; pki=0
    p=P[0]; v=V[0]; ps,pe=peaks[0]
    while True:
        if p>ps and pe>pre_p:
            s,e=sorted([p,ps,pe,pre_p])[1:3]
            content.append((s,e,v))
            try:
                pre_p=p; pi+=1; p=P[pi]; v=V[pi]
            except IndexError:
                break
        elif pre_p>=pe:
            if content:
                # close
                tsummit=[]; sv=0
                for a,b,c in content:
                    if not sv or sv<c:
                        tsummit=[(a+b)//2]; sv=c
                    elif sv==c:
                        tsummit.append((a+b)//2)
                summit=tsummit[(len(tsummit)+1)//2-1]
                out.append((content[0][0],content[-1][1],summit,sv))
            content=[]
            try:
                pki+=1; ps,pe=peaks[pki]
            except IndexError:
                break
        elif ps>=p:
            try:
                pre_p=p; pi+=1; p=P[pi]; v=V[pi]
            except IndexError:
                break
        else:
            raise Exception('no way')
    if content:
        tsummit=[]; sv=0
        for a,b,c in content:
            if not sv or sv<c:
                tsummit=[(a+b)//2]; sv=c
            elif sv==c:
                tsummit.append((a+b)//2)
        summit=tsummit[(len(tsummit)+1)//2-1]
        out.append((content[0][0],content[-1][1],summit,sv))
    return out

